1	-- CMV — Embalagem composta por Nota Fiscal (travada) + produtos_master(setor='EMBALAGENS').
2	-- Corrige o modelo do item de embalagem do construtor de CMV:
3	--   ANTES: item de embalagem apontava para `insumos` (só matéria-prima/ingredientes — não há
4	--          embalagens cadastradas lá).
5	--   AGORA: embalagem = linha de `produtos_master` com setor='EMBALAGENS' (112 ativas), com custo
6	--          COMPOSTO por uma NF específica TRAVADA (itens_nota_fiscal), campo de unidades por
7	--          embalagem (pacote→unidade) e fallback de VALOR FIXO manual quando não há NF.
8	--
9	-- Reescreve public.cmv_compute_item_cost com nova prioridade, mantendo retrocompatibilidade
10	-- total com os itens já existentes (que só têm insumo_id e/ou preco_unitario_esboco).
11	-- Recompute permanece a cargo do trigger cmv_item_recompute_trg já existente (dispara em
12	-- qualquer UPDATE da linha de cmv_itens — sem cláusula OF —, logo cobre as novas colunas).
13	-- Fonte de verdade do custo: public.cmv_compute_item_cost / public.recompute_cmv_cost.
14	-- ADR: .harness/memory-bank/decisions/ADR-20260616-cmv-embalagem-nf.md
15	
16	-- ============================================================
17	-- 1. NOVAS COLUNAS em cmv_itens (todas NULL — itens existentes inalterados)
18	-- ============================================================
19	-- FK bigint → PK int4 (produtos_master.id / itens_nota_fiscal.id são integer):
20	-- válido em Postgres (int4/int8 compartilham operator class btree); espelha o
21	-- padrão já em produção de cmv_itens.insumo_id (bigint) → insumos.id.
22	ALTER TABLE public.cmv_itens
23	  ADD COLUMN IF NOT EXISTS produto_master_id      bigint  REFERENCES public.produtos_master(id)   ON DELETE SET NULL,
24	  ADD COLUMN IF NOT EXISTS nf_item_id             bigint  REFERENCES public.itens_nota_fiscal(id)  ON DELETE SET NULL,
25	  ADD COLUMN IF NOT EXISTS unidades_por_embalagem numeric;
26	
27	-- ============================================================
28	-- 2. ÍNDICES nas novas FKs (tabela pequena; CREATE INDEX simples — sem CONCURRENTLY
29	--    para permitir rodar dentro da transação da migration)
30	-- ============================================================
31	CREATE INDEX IF NOT EXISTS cmv_itens_produto_master_id_idx ON public.cmv_itens(produto_master_id);
32	CREATE INDEX IF NOT EXISTS cmv_itens_nf_item_id_idx        ON public.cmv_itens(nf_item_id);
33	
34	-- ============================================================
35	-- 3. REESCRITA de cmv_compute_item_cost — nova prioridade de fonte de custo
36	--    Ordem: NF travada  >  insumo (legado)  >  produto_master  >  esboço (valor fixo)
37	-- ============================================================
38	CREATE OR REPLACE FUNCTION public.cmv_compute_item_cost(p_item_id bigint)
39	RETURNS numeric
40	LANGUAGE plpgsql
41	SECURITY DEFINER
42	SET search_path TO 'public'
43	AS $function$
44	DECLARE
45	  v_item        RECORD;
46	  v_insumo      RECORD;
47	  v_cost        numeric := 0;
48	  v_ratio       numeric := 1.0;
49	  v_uf          text;     -- unidade do item (lower)
50	  v_ui          text;     -- unidade de compra do insumo (lower)
51	  v_nf_valor    numeric;  -- valor_unitario da NF travada
52	  v_unidades    numeric;  -- unidades por embalagem (pacote→unidade)
53	  v_unit        numeric;  -- custo por unidade derivado
54	  v_pm_custo    numeric;  -- preco_custo do produto_master (já por unidade)
55	BEGIN
56	  SELECT * INTO v_item FROM cmv_itens WHERE id = p_item_id;
57	  IF NOT FOUND THEN RETURN 0; END IF;
58	
59	  -- 1) NF TRAVADA (prioridade máxima): custo composto pela NF escolhida, NÃO auto-latest.
60	  --    custo_por_unidade = valor_unitario_NF / unidades_por_embalagem (default 1).
61	  IF v_item.nf_item_id IS NOT NULL THEN
62	    SELECT valor_unitario INTO v_nf_valor
63	      FROM itens_nota_fiscal
64	     WHERE id = v_item.nf_item_id;
65	    IF FOUND AND coalesce(v_nf_valor, 0) > 0 THEN
66	      -- NULL ou 0 em unidades_por_embalagem → 1 (pacote = 1 unidade).
67	      v_unidades := NULLIF(coalesce(v_item.unidades_por_embalagem, 1), 0);
68	      IF v_unidades IS NULL THEN v_unidades := 1; END IF;
69	      v_unit := v_nf_valor / v_unidades;
70	      v_cost := v_unit * coalesce(v_item.quantidade, 0);
71	      RETURN coalesce(v_cost, 0);
72	    END IF;
73	  END IF;
74	
75	  -- 2) INSUMO real (legado) — preço de compra com conversão auto entre unidades standard.
76	  IF v_item.insumo_id IS NOT NULL THEN
77	    SELECT preco_custo, unidade_compra, fator_conversao
78	      INTO v_insumo
79	      FROM insumos WHERE id = v_item.insumo_id;
80	    IF FOUND AND v_insumo.preco_custo IS NOT NULL THEN
81	      v_uf := lower(coalesce(v_item.unidade, ''));
82	      v_ui := lower(coalesce(v_insumo.unidade_compra, ''));
83	
84	      IF    v_uf = v_ui THEN                       v_ratio := 1.0;
85	      ELSIF v_uf = 'g'  AND v_ui = 'kg' THEN       v_ratio := 0.001;
86	      ELSIF v_uf = 'kg' AND v_ui = 'g'  THEN       v_ratio := 1000;
87	      ELSIF v_uf = 'ml' AND v_ui = 'l'  THEN       v_ratio := 0.001;
88	      ELSIF v_uf = 'l'  AND v_ui = 'ml' THEN       v_ratio := 1000;
89	      ELSIF v_uf = 'mg' AND v_ui = 'g'  THEN       v_ratio := 0.001;
90	      ELSIF v_uf = 'g'  AND v_ui = 'mg' THEN       v_ratio := 1000;
91	      ELSE
92	        -- Unidades não-standard (pack, un, pote, cx): fator_conversao manual.
93	        IF v_insumo.fator_conversao IS NOT NULL AND v_insumo.fator_conversao > 0 THEN
94	          v_ratio := 1.0 / v_insumo.fator_conversao;
95	        ELSE
96	          v_ratio := 1.0;
97	        END IF;
98	      END IF;
99	
100	      v_cost := v_insumo.preco_custo * coalesce(v_item.quantidade, 0) * v_ratio;
101	    END IF;
102	  END IF;
103	
104	  -- 3) VALOR FIXO MANUAL (preco_unitario_esboco) — escolha EXPLÍCITA do usuário,
105	  --    tem prioridade sobre o preço de cadastro do produto_master. Se setado (mesmo 0),
106	  --    é honrado e bloqueia o fallback de cadastro abaixo.
107	  IF v_cost = 0 AND v_item.preco_unitario_esboco IS NOT NULL THEN
108	    v_cost := v_item.preco_unitario_esboco * coalesce(v_item.quantidade, 0);
109	  END IF;
110	
111	  -- 4) PRODUTO_MASTER (embalagem do setor EMBALAGENS) — preço de cadastro como ÚLTIMO
112	  --    fallback automático, só quando não há NF, insumo nem valor fixo explícito.
113	  --    preco_custo já é por unidade.
114	  IF v_cost = 0 AND v_item.preco_unitario_esboco IS NULL AND v_item.produto_master_id IS NOT NULL THEN
115	    SELECT preco_custo INTO v_pm_custo
116	      FROM produtos_master WHERE id = v_item.produto_master_id;
117	    IF coalesce(v_pm_custo, 0) > 0 THEN
118	      v_cost := v_pm_custo * coalesce(v_item.quantidade, 0);
119	    END IF;
120	  END IF;
121	
122	  RETURN coalesce(v_cost, 0);
123	END;
124	$function$;
125	
126	-- ============================================================
127	-- 4. Backfill defensivo — recomputa todas as CMVs existentes para garantir consistência
128	--    da custo_calculado após a redefinição da função (idempotente; itens existentes
129	--    permanecem com o MESMO custo, pois não têm as novas colunas).
130	-- ============================================================
131	DO $$
132	DECLARE
133	  v_cmv_id bigint;
134	BEGIN
135	  FOR v_cmv_id IN SELECT id FROM public.cmv_fichas LOOP
136	    PERFORM public.recompute_cmv_cost(v_cmv_id);
137	  END LOOP;
138	END $$;
139	
140	-- ============================================================
141	-- RLS: nenhuma mudança necessária. As novas colunas pertencem à própria linha de
142	-- cmv_itens, já coberta pela policy auth_all_cmv_itens (FOR ALL TO authenticated
143	-- USING(true) WITH CHECK(true)). produtos_master e itens_nota_fiscal já têm suas
144	-- próprias policies; cmv_compute_item_cost roda SECURITY DEFINER e lê ambas com
145	-- search_path travado em 'public'.
146	-- ============================================================
147	
148	-- ============================================================
149	-- DOWN (referência):
150	--   -- Restaurar a versão anterior da função (sem NF/produto_master):
151	--   --   ver supabase/migrations/20260612160000_cmv_fichas_itens.sql §3
152	--   DROP INDEX IF EXISTS public.cmv_itens_nf_item_id_idx;
153	--   DROP INDEX IF EXISTS public.cmv_itens_produto_master_id_idx;
154	--   ALTER TABLE public.cmv_itens
155	--     DROP COLUMN IF EXISTS unidades_por_embalagem,
156	--     DROP COLUMN IF EXISTS nf_item_id,
157	--     DROP COLUMN IF EXISTS produto_master_id;
158	-- ============================================================
159

1	import { useState, useEffect, useCallback } from 'react';
2	import { supabase } from '@/integrations/supabase/client';
3	
4	export type CmvNodeKind = 'cmv' | 'ficha' | 'insumo' | 'nf' | 'item';
5	
