15	  id: number;
16	  nome: string;
17	  custo_calculado: number | null;
18	  rendimento_quantidade: number;
19	  rendimento_unidade: string;
20	  status: string;
21	}
22	
23	export interface RawCmvInsumo {
24	  id: number;
25	  nome: string;
26	  preco_custo: number | null;
27	  unidade_compra: string | null;
28	  unidade_producao: string | null;
29	  categoria: string | null;
30	  fornecedor_principal: string | null;
