97	-- ============================================================
98	-- 3. FUNÇÃO DE CUSTO DO ITEM (espelha public.compute_item_cost — mesma conversão de unidade)
99	-- ============================================================
100	CREATE OR REPLACE FUNCTION public.cmv_compute_item_cost(p_item_id bigint)
101	RETURNS numeric
102	LANGUAGE plpgsql
103	SECURITY DEFINER
104	SET search_path TO 'public'
105	AS $function$
106	DECLARE
107	  v_item   RECORD;
108	  v_insumo RECORD;
109	  v_cost   numeric := 0;
110	  v_ratio  numeric := 1.0;
111	  v_uf     text;  -- unidade do item (lower)
112	  v_ui     text;  -- unidade de compra do insumo (lower)
113	BEGIN
114	  SELECT * INTO v_item FROM cmv_itens WHERE id = p_item_id;
115	  IF NOT FOUND THEN RETURN 0; END IF;
116	
117	  -- 1) INSUMO real (preço de compra) com conversão auto entre unidades standard
118	  IF v_item.insumo_id IS NOT NULL THEN
119	    SELECT preco_custo, unidade_compra, fator_conversao
120	      INTO v_insumo
121	      FROM insumos WHERE id = v_item.insumo_id;
122	    IF FOUND AND v_insumo.preco_custo IS NOT NULL THEN
123	      v_uf := lower(coalesce(v_item.unidade, ''));
124	      v_ui := lower(coalesce(v_insumo.unidade_compra, ''));
125	
126	      IF    v_uf = v_ui THEN                       v_ratio := 1.0;
127	      ELSIF v_uf = 'g'  AND v_ui = 'kg' THEN       v_ratio := 0.001;
128	      ELSIF v_uf = 'kg' AND v_ui = 'g'  THEN       v_ratio := 1000;
129	      ELSIF v_uf = 'ml' AND v_ui = 'l'  THEN       v_ratio := 0.001;
130	      ELSIF v_uf = 'l'  AND v_ui = 'ml' THEN       v_ratio := 1000;
131	      ELSIF v_uf = 'mg' AND v_ui = 'g'  THEN       v_ratio := 0.001;
132	      ELSIF v_uf = 'g'  AND v_ui = 'mg' THEN       v_ratio := 1000;
133	      ELSE
134	        -- Unidades não-standard (pack, un, pote, cx): fator_conversao manual
135	        IF v_insumo.fator_conversao IS NOT NULL AND v_insumo.fator_conversao > 0 THEN
136	          v_ratio := 1.0 / v_insumo.fator_conversao;
137	        ELSE
138	          v_ratio := 1.0;
139	        END IF;
140	      END IF;
141	
142	      v_cost := v_insumo.preco_custo * coalesce(v_item.quantidade, 0) * v_ratio;
143	    END IF;
144	  END IF;
145	
146	  -- 2) FALLBACK: esboço (preço livre no item)
147	  IF v_cost = 0 AND v_item.preco_unitario_esboco IS NOT NULL THEN
148	    v_cost := v_item.preco_unitario_esboco * coalesce(v_item.quantidade, 0);
149	  END IF;
150	
151	  RETURN coalesce(v_cost, 0);
152	END;
153	$function$;
154	
155	-- ============================================================
156	-- 4. RECÁLCULO DO TOTAL DA CMV
157	--    custo = custo UNITÁRIO da ficha (custo_calculado / rendimento_quantidade) + Σ itens
158	-- ============================================================
159	CREATE OR REPLACE FUNCTION public.recompute_cmv_cost(p_cmv_id bigint)
160	RETURNS void
161	LANGUAGE plpgsql
162	SECURITY DEFINER
163	SET search_path TO 'public'
164	AS $function$
165	DECLARE
166	  v_item_id        bigint;
167	  v_new_cost       numeric;
168	  v_itens_total    numeric := 0;
169	  v_ficha_unit     numeric := 0;
170	  v_total          numeric := 0;
171	  v_old_total      numeric;
172	  v_ficha_id       bigint;
173	  v_ficha_custo    numeric;
174	  v_ficha_rend     numeric;
175	  v_was_in         text;
176	BEGIN
177	  -- Guard anti-recursão (espelha app.in_recompute das fichas)
178	  v_was_in := current_setting('app.in_cmv_recompute', true);
179	  PERFORM set_config('app.in_cmv_recompute', 'true', true);
180	
181	  -- Recomputar cada item
182	  FOR v_item_id IN SELECT id FROM cmv_itens WHERE cmv_id = p_cmv_id LOOP
183	    v_new_cost := cmv_compute_item_cost(v_item_id);
184	    UPDATE cmv_itens SET custo_calculado = v_new_cost, updated_at = now()
185	     WHERE id = v_item_id;
186	    v_itens_total := v_itens_total + coalesce(v_new_cost, 0);
187	  END LOOP;
188	
189	  -- Custo unitário da ficha técnica atrelada
190	  SELECT cf.ficha_tecnica_id, ft.custo_calculado, ft.rendimento_quantidade
191	    INTO v_ficha_id, v_ficha_custo, v_ficha_rend
192	    FROM cmv_fichas cf
193	    JOIN fichas_tecnicas ft ON ft.id = cf.ficha_tecnica_id
194	   WHERE cf.id = p_cmv_id;
195	
196	  IF v_ficha_id IS NOT NULL AND coalesce(v_ficha_rend, 0) > 0 THEN
197	    v_ficha_unit := coalesce(v_ficha_custo, 0) / v_ficha_rend;
198	  END IF;
199	
200	  v_total := v_ficha_unit + v_itens_total;
201	
202	  SELECT custo_calculado INTO v_old_total FROM cmv_fichas WHERE id = p_cmv_id;
203	  IF v_old_total IS DISTINCT FROM v_total THEN
204	    UPDATE cmv_fichas
205	       SET custo_calculado = v_total, updated_at = now()
206	     WHERE id = p_cmv_id;
207	  END IF;
208	
209	  PERFORM set_config('app.in_cmv_recompute', coalesce(v_was_in, 'false'), true);
210	END;
211	$function$;
212	
213	-- ============================================================
214	-- 5. TRIGGER em cmv_itens — recálculo em INSERT/UPDATE/DELETE
215	-- ============================================================
216	CREATE OR REPLACE FUNCTION public.trg_cmv_item_recompute()
217	RETURNS trigger
218	LANGUAGE plpgsql
219	SECURITY DEFINER
220	SET search_path TO 'public'
221	AS $function$
222	BEGIN
223	  IF current_setting('app.in_cmv_recompute', true) = 'true' THEN
224	    RETURN coalesce(NEW, OLD);
225	  END IF;
226	
227	  IF TG_OP = 'DELETE' THEN
228	    PERFORM recompute_cmv_cost(OLD.cmv_id);
229	    RETURN OLD;
230	  ELSIF TG_OP = 'UPDATE' THEN
231	    IF OLD.cmv_id IS DISTINCT FROM NEW.cmv_id THEN
232	      PERFORM recompute_cmv_cost(OLD.cmv_id);
233	    END IF;
234	    PERFORM recompute_cmv_cost(NEW.cmv_id);
235	    RETURN NEW;
236	  ELSE
237	    PERFORM recompute_cmv_cost(NEW.cmv_id);
238	    RETURN NEW;
239	  END IF;
240	END;
241	$function$;
242	
243	DROP TRIGGER IF EXISTS cmv_item_recompute_trg ON public.cmv_itens;
244	CREATE TRIGGER cmv_item_recompute_trg
245	  AFTER INSERT OR UPDATE OR DELETE ON public.cmv_itens
246	  FOR EACH ROW EXECUTE FUNCTION public.trg_cmv_item_recompute();
247	
248	-- ============================================================
249	-- 6. PROPAGAÇÃO — quando o custo/rendimento da ficha muda, recomputa as CMVs ligadas
250	-- ============================================================
251	CREATE OR REPLACE FUNCTION public.trg_ficha_propagate_cmv()
252	RETURNS trigger
253	LANGUAGE plpgsql
254	SECURITY DEFINER
255	SET search_path TO 'public'
256	AS $function$
257	DECLARE
258	  v_cmv_id bigint;
259	BEGIN
260	  FOR v_cmv_id IN SELECT id FROM cmv_fichas WHERE ficha_tecnica_id = NEW.id LOOP
261	    PERFORM recompute_cmv_cost(v_cmv_id);
262	  END LOOP;
263	  RETURN NEW;
264	END;
265	$function$;
266	
267	DROP TRIGGER IF EXISTS ficha_propagate_cmv_trg ON public.fichas_tecnicas;
268	CREATE TRIGGER ficha_propagate_cmv_trg
269	  AFTER UPDATE OF custo_calculado, rendimento_quantidade ON public.fichas_tecnicas
270	  FOR EACH ROW
271	  WHEN (OLD.custo_calculado IS DISTINCT FROM NEW.custo_calculado
272	        OR OLD.rendimento_quantidade IS DISTINCT FROM NEW.rendimento_quantidade)
273	  EXECUTE FUNCTION public.trg_ficha_propagate_cmv();
274	
