276	-- 7. updated_at em cmv_fichas (BEFORE UPDATE)
277	-- ============================================================
278	CREATE OR REPLACE FUNCTION public.set_cmv_fichas_updated_at()
279	RETURNS trigger
280	LANGUAGE plpgsql
