287	$function$;
288	
289	DROP TRIGGER IF EXISTS trg_cmv_fichas_updated_at ON public.cmv_fichas;
290	CREATE TRIGGER trg_cmv_fichas_updated_at
291	  BEFORE UPDATE ON public.cmv_fichas
